SOURCE_RELATIVE_PATH = Path(
    "notebooks/02_feature_extraction/"
    "02f_temporal_discontinuity_QTEMP_v0_3_1_FINALIZATION_SOURCE.ipynb"
)


def build_notebook() -> dict:
    """Return the authoritative clean QTEMP v0.3.1-r2 finalization notebook."""
    return json.loads(
        zlib.decompress(
            base64.b85decode(PAYLOAD.encode("ascii"))
        ).decode("utf-8")
    )


def project_root() -> Path:
    return Path(__file__).resolve().parents[1]


def write_notebook(destination: Path | None = None) -> Path:
    output = destination or (
        project_root() / SOURCE_RELATIVE_PATH
    )
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        json.dumps(
            build_notebook(),
            ensure_ascii=False,
            indent=1,
        )
        + "\n",
        encoding="utf-8",
    )
    return output


if __name__ == "__main__":
    print(write_notebook())
